public with sharing class DownloadFilesController {
    public static PageReference downloadFiles() {
        // Obtén el Id del registro actual
        String recordId = ApexPages.currentPage().getParameters().get('id');

        // Consulta los archivos adjuntos o archivos de contenido relacionados
        List<ContentDocumentLink> documentLinks = [SELECT ContentDocumentId FROM ContentDocumentLink WHERE LinkedEntityId = :recordId];

        // Crea una lista para almacenar las URLs de descarga de los archivos
        List<String> downloadUrls = new List<String>();

        for(ContentDocumentLink link : documentLinks) {
            // Construye la URL de descarga para cada archivo
            downloadUrls.add('/sfc/servlet.shepherd/document/download/' + link.ContentDocumentId);
        }

        // Crea una cadena que contiene todas las URL de descarga separadas por comas
        String downloadUrlsString = String.join(downloadUrls, ',');

        // Redirecciona a la página de descarga de archivos
        PageReference downloadPage = new PageReference('/sfc/servlet.shepherd/document/download/?files=' + downloadUrlsString);
        downloadPage.setRedirect(true);

        return downloadPage;
    }
}
